const today = $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd');
const rawItems = $input.all().map(item => item.json);
const tasks = rawItems.filter(t => t && t.done === false);

const overdue = tasks.filter(t => t.due && t.due < today);
const priorityCounts = { high: 0, normal: 0, low: 0 };
const overdueByPriority = { high: 0, normal: 0, low: 0 };

tasks.forEach(t => {
  const p = t.priority || 'normal';
  if (priorityCounts[p] !== undefined) priorityCounts[p]++;
});

overdue.forEach(t => {
  const p = t.priority || 'normal';
  if (overdueByPriority[p] !== undefined) overdueByPriority[p]++;
});

const criticalTasks = overdue
  .filter(t => t.priority === 'high')
  .map(t => ({ id: t.id, title: t.title, due: t.due }));

const overdueRatio = tasks.length > 0 
  ? Number(((overdue.length / tasks.length) * 100).toFixed(1))
  : 0;

const summaryText = `[TODO Alert ${today}] Открытых задач: ${tasks.length}, Просрочено: ${overdue.length} (${overdueRatio}%). Критических (High): ${overdueByPriority.high}`;

return [{
  json: {
    date: today,
    total_pending: tasks.length,
    total_overdue: overdue.length,
    overdue_percentage: overdueRatio,
    by_priority: priorityCounts,
    overdue_by_priority: overdueByPriority,
    critical_high_overdue: criticalTasks,
    summary: summaryText
  }
}];
